def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
    O.mkdir(exist_ok=False);a=read(D/'fixed_foot_probe_134/independent_fixed_audit_135.json');v=read(D/'fixed_foot_probe_134/independent_dual_view_audit_136.json');d=read(D/'fixed_diagnosis_140/recorded_diagnosis.json');video=read(D/'all_attempts_video_audit_138/independent_audit.json')
