    for k,p in enumerate(copies):shutil.copy2(p,O/f'{k:02d}_{p.name}')
    (O/'paired_effort.json').write_text(json.dumps(a['paired_effort'],indent=2))
    fig,ax=plt.subplots(figsize=(10,4.7));labels=['Stable','Clean','Slipping','Unwanted contact union','Physical failure'];keys=['stable','clean','slipping','unwanted_contacts','physical_failures'];x=np.arange(5)
    for shift,source,color,label in [(-.19,'best_probe','#507b89','Best normal3s (24 trials)'),(.19,'candidate','#bb634e','Rejected gated134 (24 trials)')]:
        vals=[a[source][k] for k in keys];bars=ax.bar(x+shift,vals,.36,color=color,label=label);ax.bar_label(bars,padding=3)
    ax.set_xticks(x,labels,rotation=12);ax.set_ylim(0,26);ax.set_ylabel('Trials /24');ax.legend(loc='upper right');ax.set_title('Four added physical failures; no clean gain or loss');fig.tight_layout();fig.savefig(O/'comparison.png',dpi=160);plt.close(fig)
